#include <cstdio>
#include <vector>
#include <string>
#include <map>
#include <algorithm>
#include <iostream>

int main() {
    int n;
    scanf("%d", &n);
    std::map<std::string, std::vector<std::string>> groups;
    for (int i = 0; i < n; ++i) {
        std::string w;
        std::cin >> w;
        std::string key = w;
        std::sort(key.begin(), key.end());   // 排序后的串作为 key
        groups[key].push_back(w);
    }
    std::vector<std::vector<std::string>> res;
    for (auto &kv : groups) {                // 先收集各组
        auto v = kv.second;
        std::sort(v.begin(), v.end());       // 组内字典序
        res.push_back(v);
    }
    std::sort(res.begin(), res.end(),        // 组间按首词字典序
              [](const std::vector<std::string> &a,
                 const std::vector<std::string> &b) { return a[0] < b[0]; });
    for (auto &v : res) {
        for (size_t i = 0; i < v.size(); ++i) {
            if (i) printf(" ");
            printf("%s", v[i].c_str());
        }
        printf("\n");
    }
    return 0;
}
